const FEATURED_BRANDS = [
  "Google", "Microsoft", "Amazon", "Meta", "Flipkart", "Swiggy", "Zomato",
  "PhonePe", "Razorpay", "CRED", "Nykaa", "Deloitte", "Accenture", "TCS",
  "Infosys", "Wipro", "NVIDIA", "Salesforce", "Adobe", "Zoho", "Zerodha",
  "Zepto", "Blinkit", "Lenskart", "Dream11", "Freshworks",
];

export function buildSeedCompanies() {
  const all = [...SEED_COMPANIES, ...ADDITIONAL_COMPANIES];
  const seen = new Set();
  const out = [];
  all.forEach((c) => {
    if (seen.has(c.name)) return;
    seen.add(c.name);
    const featured = FEATURED_BRANDS.includes(c.name) || c.name.length % 3 === 0;
    out.push({
      name: c.name,
      slug: slugify(c.name),
      industry: c.industry,
      location: c.location,
      companySize: c.companySize,
      description: c.description,
      website: c.website,
      founded: c.founded,
      headquarters: c.location,
      isPartner: false,
      isVerified: featured,
      isFeatured: featured,
      hiringStatus: "unknown",
    });
  });
  return out;
}

