// Additional jobs generated to cover extra roles (rewritten without demo copy).
export const EXTRA_JOB_DEFS = [
  { title: "DevOps Engineer", category: "Software Development", skills: ["Docker", "Kubernetes", "CI/CD", "AWS"] },
  { title: "QA Engineer", category: "Software Development", skills: ["Testing", "Selenium", "Automation"] },
  { title: "Android Developer", category: "Software Development", skills: ["Kotlin", "Android", "Java"] },
  { title: "Business Analyst", category: "Business Development", skills: ["SQL", "Excel", "Requirements"] },
  { title: "Account Manager", category: "Sales", skills: ["CRM", "Communication", "Clients"] },
  { title: "Search Analyst", category: "Data Science", skills: ["SQL", "Python", "Analytics"] },
];

export function buildSeedJobs(companies) {
  const jobs = SEED_JOBS.map((j) => j);
  const usedCompanyNames = new Set(SEED_JOBS.map((j) => j.companyName));
  const pool = companies.filter((c) => !usedCompanyNames.has(c.name));
  const now = Date.now();
  EXTRA_JOB_DEFS.forEach((j, idx) => {
    if (pool.length === 0) return;
    const company = pool[idx % pool.length];
    const isIntern = idx % 3 === 0;
    jobs.push({
      title: isIntern ? `${j.title} Intern` : j.title,
      companyName: company.name,
      location: company.location + (idx % 2 === 0 ? " / Remote" : ""),
      type: isIntern ? "INTERNSHIP" : idx % 2 === 0 ? "FULL_TIME" : "CONTRACT",
      workMode: idx % 3 === 0 ? "REMOTE" : "HYBRID",
      salaryMin: isIntern ? 15000 : 800000,
      salaryMax: isIntern ? 25000 : 1500000,
      isStipend: isIntern,
      experience: isIntern ? "0 - 1 year" : "1 - 4 years",
      skills: j.skills,
      category: j.category,
      description: `Join ${company.name} as a ${j.title}. Drive meaningful impact across teams while growing your craft in a fast-paced environment.`,
      responsibilities: ["Collaborate with cross-functional teams", "Own end-to-end delivery of assigned work", "Write quality, maintainable output", "Continuously learn and improve"],
      requirements: ["Relevant degree or equivalent experience", "Strong foundational skills", "Good communication", "Eagerness to learn"],
      benefits: ["Competitive compensation", "Learning culture", "Growth opportunities", "Team events"],
      createdAt: new Date(now - idx * 86400000 * 2).toISOString().slice(0, 10),
      deadline: new Date(now + 30 * 86400000).toISOString().slice(0, 10),
    });
  });
  return jobs;
}

export function slugify(name) {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}